# -*- coding: utf-8 -*-
"""Banca di frasi ES (rioplatense) -> IT per esercizi di traduzione con correzione automatica.

Ogni voce: dict(es, it[list], lvl, tags[list], gap=(forma, lemma) | None, note).
"""


def _mk(lvl, rows):
    out = []
    for es, it, tags, gap, note in rows:
        it = list(dict.fromkeys(it))
        d = dict(es=es, it=it, lvl=lvl, tags=tags.split(), note=note)
        if gap:
            d["gap"] = tuple(gap)
        out.append(d)
    return out


